mapper.select:
select u.user_id as userId, u.user_name as userName, u.nick_name as nickName, u.status as status, u.create_time as createTime, coalesce(a.owner_user_id, #{bossId}) as ownerId, ou.nick_name as ownerName, (select count(*) from jiedan_order o where (o.customer_account collate utf8mb4_general_ci = u.user_name collate utf8mb4_general_ci or exists (select 1 from jiedan_project_tester pt where pt.order_id=o.id and pt.user_id=u.user_id)) and o.del_flag = 0 and o.status != 'pending') as projectCount, (select count(*) from jiedan_order o where (o.customer_account collate utf8mb4_general_ci = u.user_name collate utf8mb4_general_ci or exists (select 1 from jiedan_project_tester pt where pt.order_id=o.id and pt.user_id=u.user_id)) and o.del_flag = 0 and o.status not in ('pending', 'done', 'cancelled')) as unfinishedCount from sys_user u join sys_user_role ur on ur.user_id = u.user_id join sys_role r on r.role_id = ur.role_id left join jiedan_account_owner a on a.user_id = u.user_id left join sys_user ou on ou.user_id = coalesce(a.owner_user_id, #{bossId}) where r.role_key = 'customer' and u.del_flag = '0'
and coalesce(a.owner_user_id, #{bossId}) = #{ownerId}
order by u.user_id desc
